export function translate(key: TranslationKey, langCode: string = "en"): string {
  const primary = TRANSLATIONS[langCode]?.[key];
  if (primary) return primary;

  // Fallback to English
  return TRANSLATIONS.en?.[key] || key;
}

/**
 * Returns the BCP47 locale code for Web Speech API text-to-speech.
 */
export function getSpeechLocale(langCode: string): string {
  const found = WORLD_LANGUAGES.find((l) => l.code === langCode);
  return found?.bcp47 || "en-US";
}

/**
 * Translates weather condition strings and WMO descriptions into the target language.
 */
export function translateCondition(condition: string, langCode: string = "en"): string {
  if (!condition) return translate("clear", langCode);
  const c = condition.toLowerCase();

  if (c.includes("thunder") || c.includes("storm")) return translate("thunderstorm", langCode);
  if (c.includes("snow") || c.includes("blizzard") || c.includes("flurries") || c.includes("sleet") || c.includes("freezing rain")) return translate("snow", langCode);
  if (c.includes("drizzle") || c.includes("light rain")) return translate("drizzle", langCode);
  if (c.includes("shower") || c.includes("heavy rain") || c.includes("rain")) return translate("rain", langCode);
  if (c.includes("fog") || c.includes("mist") || c.includes("haze")) return translate("fog", langCode);
  if (c.includes("wind") || c.includes("gale") || c.includes("breeze")) return translate("windDynamics", langCode);
  if (c.includes("cloud") || c.includes("overcast") || c.includes("partly") || c.includes("scattered") || c.includes("broken")) return translate("clouds", langCode);
  if (c.includes("sunny") || c.includes("clear")) return translate("clear", langCode);

  return condition;
}

/**
 * Formats a localized number string or unit.
 */
export function formatLocalizedNumber(num: number | string, langCode: string = "en"): string {
  if (langCode === "kn") {
    const kannadaDigits = ["೦", "೧", "೨", "೩", "೪", "೫", "೬", "೭", "೮", "೯"];
    return String(num).replace(/\d/g, (d) => kannadaDigits[parseInt(d, 10)]);
  }
  if (langCode === "ar" || langCode === "fa") {
    const arabicDigits = ["٠", "١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩"];
    return String(num).replace(/\d/g, (d) => arabicDigits[parseInt(d, 10)]);
  }
  return String(num);
}
