/**
 * Formats a localized time string with proper AM/PM and native numerals.
 */
export function formatLocalizedTime(date: Date, langCode: string = "en", bcp47: string = "en-US"): string {
  const raw = date.toLocaleTimeString(bcp47, { hour: "2-digit", minute: "2-digit" });
  if (langCode === "kn") {
    let localized = raw.replace(/\bAM\b/gi, "ಪೂರ್ವಾಹ್ನ").replace(/\bPM\b/gi, "ಅಪರಾಹ್ನ");
    return formatLocalizedNumber(localized, langCode);
  }
  return formatLocalizedNumber(raw, langCode);
}

/**
 * Formats a localized date string with native numerals.
 */
export function formatLocalizedDate(date: Date, langCode: string = "en", bcp47: string = "en-US"): string {
  const raw = date.toLocaleDateString(bcp47, { weekday: "long", month: "short", day: "numeric" });
  return formatLocalizedNumber(raw, langCode);
}
